INSERT INTO help_topic (help_topic_id, help_category_id, name, description, example, url) VALUES (1068, 22, 'LONG VARBINARY', 'Syntax:\n\nSee [MEDIUMBLOB](mediumblob.md).\n', 'CREATE TABLE long_varbinary_example (\n  example LONG VARBINARY\n);', 'https://mariadb.com/docs/server/reference/data-types/string-data-types/long-varbinary');
